source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    frame = min(counts, key=counts.get)
    fill_color = max(counts, key=counts.get)
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != fill_color or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            touches_edge = False
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == fill_color and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if not touches_edge and any(grid[y][x] == frame for y, x in component):
                for y, x in component:
                    out[y][x] = 4
    return out
'''
